// Wisp Servers (GhostLink + Verified Fast Public Fleet)
const DEFAULT_WISP_SERVERS = [
  { name: "Hydrovolter (Fastest)", url: "wss://admin.proxy.hydrovolter.com/scramjet/wisp/" },
  { name: "Mercury Workshop", url: "wss://wisp.mercurywork.shop/" },
  { name: "Anura Wisp", url: "wss://anura.pro/wisp/" },
  { name: "Boston Career Counselor", url: "wss://i-ready.math.bostoncareercounselor.com/wisp/" },
  { name: "GL Series", url: "wss://glseries.net/wisp/" }
];

// State
let sharedScramjet = null;
let sharedConnection = null;
let sharedConnectionReady = false;
let proxyInitPromise = null;
let proxyStatus = 'uninitialized';
let proxyErrorMessage = '';

let currentTab = 'home';
let currentLoadedUrl = '';
let currentLoadedName = '';
let currentIsApp = false;
let listeningForPanicKey = false;

// Helpers
function getBasePath() {
  const basePath = location.pathname.replace(/[^/]*$/, '');
  return basePath.endsWith('/') ? basePath : basePath + '/';
}

function getStoredWisps() {
  try { return JSON.parse(localStorage.getItem('truffled_custom_wisps') || '[]'); }
  catch { return []; }
}

function getAllWispServers() {
  return [...DEFAULT_WISP_SERVERS, ...getStoredWisps()];
}

function getActiveWispUrl() {
  return localStorage.getItem('truffled_wisp_url') || DEFAULT_WISP_SERVERS[0].url;
}

function getActiveWispName() {
  const currentUrl = getActiveWispUrl();
  const found = getAllWispServers().find(s => s.url === currentUrl);
  return found ? found.name : 'Custom Server';
}

function getBackendHost() {
  const custom = localStorage.getItem('truffled_backend_host');
  if (custom && custom.trim()) {
    return custom.trim().replace(/\/+$/, '');
  }
  const host = window.location.hostname;
  if (host && host !== 'localhost' && host !== '127.0.0.1' && !host.includes('esm.sh') && !host.includes('github') && !host.includes('jsdelivr') && !host.includes('unpkg') && window.location.protocol !== 'file:') {
    return window.location.origin;
  }
  return DEFAULT_REMOTE_BACKEND;
}

function decodeUVUrl(url) {
  if (!url) return '';
  if (!url.includes('active/go/')) return url;
  const rawPart = url.split('active/go/')[1];
  try {
    const decoded = decodeURIComponent(rawPart);
    return decoded.split('').map((c, ind) => {
      return ind % 2 ? String.fromCharCode(c.charCodeAt(0) ^ 2) : c;
    }).join('');
  } catch (e) {
    return url;
  }
}

function resolveItemUrl(rawUrl) {
  if (!rawUrl) return '';
  let url = rawUrl.trim();
  if (url.includes('active/go/')) {
    url = decodeUVUrl(url);
  }
  if (url.startsWith('http://') || url.startsWith('https://') || url.startsWith('//') || url.startsWith('data:') || url.startsWith('blob:')) {
    return url;
  }
  const backend = getBackendHost();
  const clean = url.replace(/^\/+/, '');
  return backend + '/' + clean;
}

function handleImgError(img) {
  img.style.display = 'none';
  const fallback = img.nextElementSibling;
  if (fallback) fallback.style.display = 'flex';
}

function showToast(msg) {
  const toast = document.getElementById('toast');
  if (!toast) return;
  toast.textContent = msg;
  toast.classList.add('show');
  setTimeout(() => {
    toast.classList.remove('show');
  }, 2200);
}

// Ensure Scramjet and BareMux scripts are present
async function ensureProxyScriptsLoaded() {
  if (typeof $scramjetLoadController === 'undefined') {
    await new Promise((resolve, reject) => {
      const script = document.createElement('script');
      script.src = "https://cdn.jsdelivr.net/gh/Destroyed12121/Staticsj@main/JS/scramjet.all.js";
      script.onload = resolve;
      script.onerror = () => reject(new Error("Failed to load Scramjet core CDN script"));
      document.head.appendChild(script);
    });
  }

  if (!window.BareMux) {
    try {
      const BM = await import("https://cdn.jsdelivr.net/npm/@mercuryworkshop/bare-mux/dist/index.mjs");
      window.BareMux = BM;
    } catch (e) {
      console.warn("Dynamic module import fallback for BareMux:", e);
      await new Promise((resolve, reject) => {
        const script = document.createElement('script');
        script.src = "https://cdn.jsdelivr.net/npm/@mercuryworkshop/bare-mux/dist/index.js";
        script.onload = resolve;
        script.onerror = () => reject(new Error("Failed to load BareMux script"));
        document.head.appendChild(script);
      });
    }
  }
}

// Scramjet Proxy Initializer (GhostLink Engine)
async function initScramjetProxy() {
  if (location.protocol === 'file:') {
    proxyStatus = 'file_protocol';
    proxyErrorMessage = 'Service Workers cannot register on file:/// URLs due to browser security restrictions.';
    updateProxyStatusUI();
    return false;
  }

  if (proxyStatus === 'ready' && sharedScramjet) {
    return true;
  }

  if (proxyInitPromise) {
    return proxyInitPromise;
  }

  proxyInitPromise = (async () => {
    try {
      proxyStatus = 'initializing';
      updateProxyStatusUI();

      await ensureProxyScriptsLoaded();

      const basePath = getBasePath();

      if (typeof $scramjetLoadController === 'undefined') {
        throw new Error("Scramjet controller loader is not available.");
      }
      const { ScramjetController } = $scramjetLoadController();
      sharedScramjet = new ScramjetController({
        prefix: basePath + "scramjet/",
        files: {
          wasm: "https://cdn.jsdelivr.net/gh/Destroyed12121/Staticsj@main/JS/scramjet.wasm.wasm",
          all: "https://cdn.jsdelivr.net/gh/Destroyed12121/Staticsj@main/JS/scramjet.all.js",
          sync: "https://cdn.jsdelivr.net/gh/Destroyed12121/Staticsj@main/JS/scramjet.sync.js"
        }
      });

      try {
        await sharedScramjet.init();
      } catch (err) {
        if (err.message && (err.message.includes('IDBDatabase') || err.message.includes('object stores'))) {
          console.warn('Scramjet IndexedDB error, clearing cache and retrying...');
          ['scramjet-data', 'scrambase', 'ScramjetData'].forEach(db => {
            try { indexedDB.deleteDatabase(db); } catch {}
          });
          sharedScramjet = new ScramjetController({
            prefix: basePath + "scramjet/",
            files: {
              wasm: "https://cdn.jsdelivr.net/gh/Destroyed12121/Staticsj@main/JS/scramjet.wasm.wasm",
              all: "https://cdn.jsdelivr.net/gh/Destroyed12121/Staticsj@main/JS/scramjet.all.js",
              sync: "https://cdn.jsdelivr.net/gh/Destroyed12121/Staticsj@main/JS/scramjet.sync.js"
            }
          });
          await sharedScramjet.init();
        } else {
          throw err;
        }
      }

      const BM = window.BareMux;
      if (!BM || !BM.BareMuxConnection) {
        throw new Error("BareMuxConnection is unavailable.");
      }
      sharedConnection = new BM.BareMuxConnection(basePath + "bareworker.js");
      const currentWisp = getActiveWispUrl();
      await sharedConnection.setTransport(
        "https://cdn.jsdelivr.net/npm/@mercuryworkshop/epoxy-transport@2.1.28/dist/index.mjs",
        [{ wisp: currentWisp }]
      );
      sharedConnectionReady = true;

      if ('serviceWorker' in navigator) {
        const reg = await navigator.serviceWorker.register(basePath + 'sw.js', { scope: basePath });
        await navigator.serviceWorker.ready;

        const swConfig = {
          type: 'config',
          wispurl: currentWisp,
          servers: getAllWispServers(),
          autoswitch: localStorage.getItem('truffled_wisp_autoswitch') !== 'false'
        };

        const sendConfig = () => {
          const sw = reg.active || navigator.serviceWorker.controller;
          if (sw) sw.postMessage(swConfig);
        };
        sendConfig();
        setTimeout(sendConfig, 500);
        setTimeout(sendConfig, 1600);

        navigator.serviceWorker.addEventListener('message', (event) => {
          const { type, url, name } = event.data || {};
          if (type === 'wispChanged') {
            console.log("SW auto-switched Wisp to:", url);
            localStorage.setItem('truffled_wisp_url', url);
            showToast('Proxy switched to ' + (name || 'fastest server'));
            updateProxyStatusUI();
          }
        });
      }

      proxyStatus = 'ready';
      updateProxyStatusUI();
      return true;
    } catch (err) {
      console.error("Proxy init error:", err);
      proxyStatus = 'error';
      proxyErrorMessage = err.message || 'Failed to initialize Scramjet proxy';
      updateProxyStatusUI();
      return false;
    }
  })();

  return proxyInitPromise;
}

function updateProxyStatusUI() {
  const activeName = getActiveWispName();
  const sStatus = document.getElementById('settings-proxy-status-text');
  if (sStatus) {
    if (proxyStatus === 'ready') sStatus.textContent = 'Active (' + activeName + ')';
    else if (proxyStatus === 'initializing') sStatus.textContent = 'Connecting...';
    else if (proxyStatus === 'file_protocol') sStatus.textContent = 'file:/// mode (requires web server)';
    else if (proxyStatus === 'error') sStatus.textContent = 'Error: ' + proxyErrorMessage;
    else sStatus.textContent = 'Ready (' + activeName + ')';
  }

  const pBadge = document.getElementById('player-proxy-badge');
  if (pBadge) {
    pBadge.style.display = currentIsApp ? 'inline-flex' : 'none';
  }
}

// Tab Switching
function switchTab(tabId) {
  currentTab = tabId;
  document.querySelectorAll('.tab-view').forEach(view => view.classList.remove('active'));
  document.querySelectorAll('.nav-item').forEach(btn => btn.classList.remove('active'));

  const targetView = document.getElementById('view-' + tabId);
  if (targetView) targetView.classList.add('active');

  const targetBtn = document.getElementById('nav-' + tabId);
  if (targetBtn) targetBtn.classList.add('active');

  const player = document.getElementById('player-modal');
  if (player && player.classList.contains('active')) {
    closePlayer(false);
  }

  if (window.location.hash !== '#' + tabId) {
    history.pushState(null, '', '#' + tabId);
  }
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

// Launching Games & Apps
async function launchItem(name, rawUrl, isApp = false) {
  if (!rawUrl) return;
  const finalUrl = resolveItemUrl(rawUrl);
  currentLoadedUrl = finalUrl;
  currentLoadedName = name;
  currentIsApp = isApp;

  const player = document.getElementById('player-modal');
  const iframe = document.getElementById('gameframe');
  const titleEl = document.getElementById('player-title-text');
  const proxyNotice = document.getElementById('proxy-notice-overlay');
  const proxyLoading = document.getElementById('proxy-loading-overlay');

  if (titleEl) titleEl.textContent = name || 'Game';
  if (player) player.classList.add('active');
  updateProxyStatusUI();

  const appBehavior = localStorage.getItem('truffled_app_behavior') || 'proxy';

  if (isApp) {
    if (appBehavior === 'newtab') {
      window.open(finalUrl, '_blank', 'noopener,noreferrer');
      showToast('Opened in new tab');
      closePlayer(false);
      return;
    } else if (appBehavior === 'aboutblank') {
      openPlayerInAboutBlank(finalUrl);
      showToast('Opened in about:blank');
      closePlayer(false);
      return;
    }

    if (location.protocol === 'file:') {
      if (iframe) iframe.style.display = 'none';
      if (proxyLoading) proxyLoading.style.display = 'none';
      if (proxyNotice) {
        document.getElementById('notice-app-title').textContent = name;
        document.getElementById('notice-app-url').textContent = finalUrl;
        proxyNotice.style.display = 'flex';
      }
      history.pushState(null, '', '#play?name=' + encodeURIComponent(name) + '&url=' + encodeURIComponent(finalUrl) + '&app=1');
      return;
    }

    if (proxyNotice) proxyNotice.style.display = 'none';
    if (proxyLoading) {
      proxyLoading.style.display = 'flex';
      document.getElementById('proxy-loading-title').textContent = 'Connecting ' + name + '...';
    }

    const ok = await initScramjetProxy();
    if (ok && sharedScramjet) {
      const proxiedUrl = sharedScramjet.encodeUrl(finalUrl);
      if (iframe) {
        iframe.style.display = 'block';
        iframe.src = proxiedUrl;
      }
      setTimeout(() => {
        if (proxyLoading) proxyLoading.style.display = 'none';
      }, 700);
    } else {
      if (proxyLoading) proxyLoading.style.display = 'none';
      if (proxyNotice) {
        document.getElementById('notice-app-title').textContent = name;
        document.getElementById('notice-app-url').textContent = finalUrl;
        proxyNotice.style.display = 'flex';
      }
    }
  } else {
    if (proxyNotice) proxyNotice.style.display = 'none';
    if (proxyLoading) proxyLoading.style.display = 'none';
    if (iframe) {
      iframe.style.display = 'block';
      iframe.src = finalUrl;
    }
  }

  history.pushState(null, '', '#play?name=' + encodeURIComponent(name) + '&url=' + encodeURIComponent(finalUrl) + (isApp ? '&app=1' : ''));
}

function launchProxyUrl(rawUrl) {
  if (!rawUrl) return;
  let url = rawUrl.trim();
  if (!/^https?:\/\//i.test(url)) {
    if (url.includes('.') && !url.includes(' ')) {
      url = 'https://' + url;
    } else {
      url = 'https://duckduckgo.com/?t=h_&ia=web&q=' + encodeURIComponent(url);
    }
  }
  let domain = 'Web Proxy';
  try { domain = new URL(url).hostname; } catch(e) {}
  launchItem(domain, url, true);
}

function handleHomeSubmit() {
  const input = document.getElementById('uv-address');
  if (input && input.value.trim()) {
    launchProxyUrl(input.value.trim());
  }
}

function closePlayer(updateHistory = true) {
  const player = document.getElementById('player-modal');
  const iframe = document.getElementById('gameframe');
  const proxyNotice = document.getElementById('proxy-notice-overlay');
  const proxyLoading = document.getElementById('proxy-loading-overlay');
  if (iframe) {
    iframe.src = 'about:blank';
    iframe.style.display = 'block';
  }
  if (proxyNotice) proxyNotice.style.display = 'none';
  if (proxyLoading) proxyLoading.style.display = 'none';
  currentLoadedUrl = '';
  currentLoadedName = '';
  currentIsApp = false;
  if (player) player.classList.remove('active');
  updateProxyStatusUI();
  if (updateHistory) {
    history.pushState(null, '', '#' + currentTab);
  }
}

function reloadPlayer() {
  const iframe = document.getElementById('gameframe');
  if (iframe) {
    try {
      iframe.contentWindow?.location?.reload();
    } catch (e) {
      const s = iframe.src;
      iframe.src = 'about:blank';
      setTimeout(() => { iframe.src = s; }, 50);
    }
  }
}

function proxyHistoryBack() {
  const iframe = document.getElementById('gameframe');
  try { iframe.contentWindow?.history?.back(); } catch (e) {}
}

function proxyHistoryForward() {
  const iframe = document.getElementById('gameframe');
  try { iframe.contentWindow?.history?.forward(); } catch (e) {}
}

function togglePlayerFullscreen() {
  const player = document.getElementById('player-modal');
  if (!document.fullscreenElement) {
    if (player.requestFullscreen) player.requestFullscreen();
    else if (player.webkitRequestFullscreen) player.webkitRequestFullscreen();
  } else {
    if (document.exitFullscreen) document.exitFullscreen();
    else if (document.webkitExitFullscreen) document.webkitExitFullscreen();
  }
}

function openPlayerInAboutBlank(url) {
  const target = url || currentLoadedUrl || window.location.href;
  if (!target) return;
  const win = window.open('about:blank', '_blank');
  if (!win) {
    alert("Popup blocked! Please allow popups for this site.");
    return;
  }
  const doc = win.document;
  doc.open();
  doc.write('<iframe src="' + target + '" style="position:fixed;top:0;left:0;bottom:0;right:0;width:100%;height:100%;border:none;margin:0;padding:0;overflow:hidden;"></iframe>');
  doc.close();
  doc.title = currentLoadedName || 'New Tab';
}

function copyPlayerLink() {
  const fullUrl = window.location.href;
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(fullUrl).then(() => {
      showToast('Link copied to clipboard!');
    }).catch(() => {
      prompt('Copy this link:', fullUrl);
    });
  } else {
    prompt('Copy this link:', fullUrl);
  }
}

function forceDirectIframe() {
  const proxyNotice = document.getElementById('proxy-notice-overlay');
  const iframe = document.getElementById('gameframe');
  if (proxyNotice) proxyNotice.style.display = 'none';
  if (iframe) {
    iframe.style.display = 'block';
    iframe.src = currentLoadedUrl;
  }
  showToast('Loading direct iframe...');
}

function pickRandomGame() {
  const gallery = document.getElementById('games-gallery');
  if (!gallery) return;
  const items = Array.from(gallery.querySelectorAll('.game')).filter(el => {
    const name = el.getAttribute('data-name');
    return name && name !== 'Game Suggestions' && name !== 'Random game';
  });
  if (items.length === 0) return;
  const picked = items[Math.floor(Math.random() * items.length)];
  picked.click();
}

function pickRandomApp() {
  const gallery = document.getElementById('apps-gallery');
  if (!gallery) return;
  const items = Array.from(gallery.querySelectorAll('.game')).filter(el => {
    const name = el.getAttribute('data-name');
    return name && name !== 'App Suggestions' && name !== 'Random app';
  });
  if (items.length === 0) return;
  const picked = items[Math.floor(Math.random() * items.length)];
  picked.click();
}

// Search & Filter Logic
function filterGallery(galleryId, inputId, countId, singularText) {
  const gallery = document.getElementById(galleryId);
  const input = document.getElementById(inputId);
  const countEl = document.getElementById(countId);
  if (!gallery || !input) return;

  const filter = input.value.toLowerCase().trim();
  const items = gallery.querySelectorAll('.game');
  let visibleCount = 0;

  items.forEach(item => {
    const title = (item.getAttribute('data-name') || '').toLowerCase();
    if (title.includes(filter)) {
      item.style.display = '';
      visibleCount++;
    } else {
      item.style.display = 'none';
    }
  });

  if (countEl) {
    countEl.textContent = 'Showing ' + visibleCount + ' ' + (visibleCount === 1 ? singularText : singularText + 's');
  }
}

// Autocomplete Setup
function setupSearchWithAutocomplete(inputId, autoId, dataset) {
  const input = document.getElementById(inputId);
  const auto = document.getElementById(autoId);
  if (!input || !auto) return;

  input.addEventListener('input', () => {
    const val = input.value.toLowerCase().trim();
    if (!val) {
      auto.style.display = 'none';
      auto.innerHTML = '';
      return;
    }

    const matches = dataset.filter(d => d.name.toLowerCase().includes(val)).slice(0, 6);
    if (!matches.length) {
      auto.style.display = 'none';
      auto.innerHTML = '';
      return;
    }

    auto.innerHTML = '';
    matches.forEach(m => {
      const row = document.createElement('div');
      row.className = 'autocomplete-item';
      row.innerHTML = '<img src="' + m.thumbnail + '" alt="' + m.name + '" onerror="handleImgError(this)" /><span>' + m.name + '</span>';
      row.onclick = () => {
        auto.style.display = 'none';
        input.value = '';
        launchItem(m.name, m.url, !!m.isApp);
      };
      auto.appendChild(row);
    });
    auto.style.display = 'block';
  });

  input.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      const first = auto.querySelector('.autocomplete-item');
      if (first && auto.style.display !== 'none') {
        first.click();
      }
    }
  });

  document.addEventListener('click', (e) => {
    if (!input.contains(e.target) && !auto.contains(e.target)) {
      auto.style.display = 'none';
    }
  });
}

// Panic Key
function setupPanicKey() {
  const panicKey = localStorage.getItem('truffled_panicKey') || "'";
  const panicUrl = localStorage.getItem('truffled_panicUrl') || 'https://www.google.com';

  const keyDisplay = document.getElementById('currentPanicKey');
  if (keyDisplay) keyDisplay.textContent = "panic key: " + panicKey;

  const urlInput = document.getElementById('panicUrlInput');
  if (urlInput) urlInput.value = panicUrl;

  window.addEventListener('keydown', (e) => {
    if (listeningForPanicKey) {
      e.preventDefault();
      const newKey = e.key;
      localStorage.setItem('truffled_panicKey', newKey);
      listeningForPanicKey = false;
      if (keyDisplay) keyDisplay.textContent = "panic key: " + newKey;
      showToast("Panic key changed to: '" + newKey + "'");
      return;
    }

    const savedKey = localStorage.getItem('truffled_panicKey') || "'";
    if (e.key === savedKey) {
      e.preventDefault();
      const safeUrl = localStorage.getItem('truffled_panicUrl') || 'https://www.google.com';
      window.location.replace(safeUrl);
    }
  });
}

function changePanicKey() {
  listeningForPanicKey = true;
  showToast("Press any key to set as your panic key...");
}

function savePanicUrl() {
  const input = document.getElementById('panicUrlInput');
  if (!input) return;
  let url = input.value.trim();
  if (url) {
    if (!url.startsWith('http://') && !url.startsWith('https://')) {
      url = 'https://' + url;
    }
    localStorage.setItem('truffled_panicUrl', url);
    showToast('Panic redirect URL saved!');
  }
}

// Data saving
function exportData() {
  const data = {
    exportedAt: new Date().toISOString(),
    localStorage: { ...localStorage }
  };
  const json = JSON.stringify(data, null, 2);
  const blob = new Blob([json], { type: 'application/json' });
  const link = document.createElement('a');
  link.href = URL.createObjectURL(blob);
  link.download = 'truffled_backup_' + new Date().toISOString().slice(0, 10) + '.json';
  link.click();
  showToast('Data exported!');
}

function importData() {
  const input = document.createElement('input');
  input.type = 'file';
  input.accept = '.json';
  input.onchange = (e) => {
    const f = e.target.files[0];
    if (!f) return;
    const r = new FileReader();
    r.onload = (ev) => {
      try {
        const d = JSON.parse(ev.target.result);
        if (d.localStorage) {
          Object.entries(d.localStorage).forEach(([k, v]) => localStorage.setItem(k, v));
        }
        showToast('Import successful! Reloading...');
        setTimeout(() => location.reload(), 800);
      } catch (err) {
        alert('Invalid file format');
      }
    };
    r.readAsText(f);
  };
  input.click();
}

function clearAllData() {
  if (confirm("Are you sure you want to clear all Truffled preferences and stored settings?")) {
    localStorage.clear();
    showToast('All data cleared.');
    setTimeout(() => location.reload(), 600);
  }
}

// Wisp settings
function setupWispSettings() {
  const select = document.getElementById('wisp-server-select');
  const customInput = document.getElementById('custom-wisp-input');
  const currentWisp = getActiveWispUrl();

  if (select) {
    const isDefault = DEFAULT_WISP_SERVERS.some(s => s.url === currentWisp);
    if (isDefault) {
      select.value = currentWisp;
      if (customInput) customInput.style.display = 'none';
    } else {
      select.value = 'custom';
      if (customInput) {
        customInput.style.display = 'block';
        customInput.value = currentWisp;
      }
    }
  }
}

function handleWispSelectChange() {
  const select = document.getElementById('wisp-server-select');
  const customInput = document.getElementById('custom-wisp-input');
  if (!select) return;

  if (select.value === 'custom') {
    if (customInput) customInput.style.display = 'block';
  } else {
    if (customInput) customInput.style.display = 'none';
    localStorage.setItem('truffled_wisp_url', select.value);
    showToast('Wisp server set: ' + select.options[select.selectedIndex].text);
    applyWispServer(select.value);
  }
}

function saveCustomWisp() {
  const input = document.getElementById('custom-wisp-input');
  if (!input) return;
  const url = input.value.trim();
  if (!url.startsWith('ws://') && !url.startsWith('wss://')) {
    alert('Wisp server URL must start with wss:// or ws://');
    return;
  }
  localStorage.setItem('truffled_wisp_url', url);
  showToast('Custom Wisp server applied!');
  applyWispServer(url);
}

async function applyWispServer(url) {
  updateProxyStatusUI();
  if (sharedConnectionReady && sharedConnection) {
    try {
      await sharedConnection.setTransport(
        "https://cdn.jsdelivr.net/npm/@mercuryworkshop/epoxy-transport@2.1.28/dist/index.mjs",
        [{ wisp: url }]
      );
    } catch (e) {}
  }
  if (navigator.serviceWorker && navigator.serviceWorker.controller) {
    navigator.serviceWorker.controller.postMessage({ type: 'config', wispurl: url });
  }
}

// Hash Routing
function handleHashChange() {
  const hash = window.location.hash || '#home';
  if (hash.startsWith('#play')) {
    const params = new URLSearchParams(hash.slice(6));
    const name = params.get('name') || 'Game';
    const rawUrl = params.get('url') || '';
    const isApp = params.get('app') === '1';
    if (rawUrl) {
      launchItem(name, rawUrl, isApp);
    }
  } else {
    const tabName = hash.replace('#', '');
    if (['home', 'games', 'apps', 'proxy', 'tools', 'settings'].includes(tabName)) {
      switchTab(tabName);
    } else {
      switchTab('home');
    }
  }
}

// Dynamic Scroll Grid Parallax (Exact Truffled.lol feature)
window.addEventListener('scroll', () => {
  const scrollY = window.scrollY;
  const offsetX = (scrollY * 0.1) % 50; 
  const offsetY = (scrollY * 0.1) % 50;
  document.body.style.setProperty('--scroll-offset-x', offsetX + 'px');
  document.body.style.setProperty('--scroll-offset-y', offsetY + 'px');
});

// Initialization
window.addEventListener('DOMContentLoaded', () => {
  // 1. Pick authentic quote
  const container = document.getElementById("random-text");
  if (container && RANDOM_QUOTES.length) {
    const selected = RANDOM_QUOTES[Math.floor(Math.random() * RANDOM_QUOTES.length)];
    container.textContent = selected;
  }

  // 2. Setup Autocomplete
  const allItems = [
    ...GAMES_DATA.map(g => ({ ...g, isApp: false })),
    ...APPS_DATA.map(a => ({ ...a, isApp: true })),
    ...TOOLS_DATA.map(t => ({ ...t, isApp: false }))
  ];
  setupSearchWithAutocomplete('uv-address', 'home-autocomplete', allItems);
  setupSearchWithAutocomplete('games-search-input', 'games-autocomplete', GAMES_DATA);
  setupSearchWithAutocomplete('apps-search-input', 'apps-autocomplete', APPS_DATA);
  setupSearchWithAutocomplete('tools-search-input', 'tools-autocomplete', TOOLS_DATA);

  // 3. Setup Filter Listeners
  const gIn = document.getElementById('games-search-input');
  if (gIn) gIn.addEventListener('input', () => filterGallery('games-gallery', 'games-search-input', 'games-count', 'game'));

  const aIn = document.getElementById('apps-search-input');
  if (aIn) aIn.addEventListener('input', () => filterGallery('apps-gallery', 'apps-search-input', 'apps-count', 'app'));

  const tIn = document.getElementById('tools-search-input');
  if (tIn) tIn.addEventListener('input', () => filterGallery('tools-gallery', 'tools-search-input', 'tools-count', 'tool'));

  const pIn = document.getElementById('proxy-url-input');
  if (pIn) pIn.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') launchProxyUrl(pIn.value.trim());
  });

  // 4. Setup Settings & Panic
  setupPanicKey();
  setupWispSettings();

  handleHashChange();
  window.addEventListener('hashchange', handleHashChange);

  // Pre-initialize Scramjet Proxy if on HTTP/HTTPS
  if (location.protocol !== 'file:') {
    setTimeout(initScramjetProxy, 800);
  }
});

